-- US-04b Formulaire KYC : une ligne par utilisateur (étape atteinte, réponses, statut,
-- date de validation). Réponses enregistrées à chaque étape, figées à la validation.
CREATE TYPE "public"."statut_kyc" AS ENUM('en_cours', 'complete');--> statement-breakpoint
CREATE TABLE "kyc" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "kyc_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"utilisateur_id" text NOT NULL,
	"etape" integer DEFAULT 1 NOT NULL,
	"reponses" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"statut" "statut_kyc" DEFAULT 'en_cours' NOT NULL,
	"valide_le" timestamp with time zone,
	"cree_le" timestamp with time zone DEFAULT now() NOT NULL,
	"modifie_le" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "kyc_utilisateur_id_unique" UNIQUE("utilisateur_id")
);
